window.di = function di(name, size, className) {
  var svg = window.DOODLE_ICONS[name];
  if (!svg) {
    console.warn("doodle icon missing:", name);
    return "";
  }
  return svg
    .replace('width="SIZE" height="SIZE"', 'width="' + size + '" height="' + size + '"')
    .replace('class="di"', 'class="di' + (className ? " " + className : "") + '"')
    .replace("<svg", '<svg aria-hidden="true" focusable="false"');
};
